import React, { useEffect, useState } from 'react';
import Table from '../components/table/Table';
import { database } from '../components/Firebase/firebaseConfig';
import { ref, onValue, update } from 'firebase/database';

const customerTableHead = [
    'STT',
    'Mã sản phẩm',
    'Tên sản phẩm',
    'Số lượng',
    'Tổng giá',
    'Tên khách hàng',
    'SĐT',
    'Địa chỉ',
    'Trạng thái'
];

const renderHead = (item, index) => <th key={index}>{item}</th>;

const Orders = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const usersRef = ref(database, 'Users');

        const unsubscribe = onValue(usersRef, (snapshot) => {
            try {
                const data = snapshot.val();
                if (data) {
                    const allOrders = [];

                    Object.entries(data).forEach(([userId, userData]) => {
                        if (userData.orders) {
                            Object.entries(userData.orders).forEach(([orderId, order]) => {
                                if (order.items && Array.isArray(order.items)) {
                                    order.items.forEach(item => {
                                        allOrders.push({
                                            id: orderId,
                                            userId: userId, // Thêm userId để update
                                            productId: item.id,
                                            productTitle: item.title,
                                            quantity: item.numberInCart,
                                            total: order.total,
                                            customerName: userData.profile_name,
                                            customerPhone: userData.phone,
                                            customerAddress: userData.address,
                                            status: order.status || 'Chờ xử lý'
                                        });
                                    });
                                }
                            });
                        }
                    });

                    setOrders(allOrders);
                }
                setLoading(false);
            } catch (err) {
                console.error("Error reading orders:", err);
                setError(err.message);
                setLoading(false);
            }
        });

        return () => unsubscribe();
    }, []);

    const handleStatusChange = (newStatus, item) => {
        if (!item.userId || !item.id) {
            console.error("Thiếu userId hoặc orderId");
            return;
        }

        const orderRef = ref(database, `Users/${item.userId}/orders/${item.id}`);
        update(orderRef, { status: newStatus })
            .then(() => {
                console.log("Đã cập nhật trạng thái:", newStatus);
            })
            .catch(err => {
                console.error("Lỗi khi cập nhật trạng thái:", err);
            });
    };

    const renderBody = (item, index) => (
        <tr key={index}>
            <td>{index + 1}</td>
            <td>{item.id || ''}</td>
            <td>{item.productTitle || 'Không có tên'}</td>
            <td>{item.quantity || 'Không có SL'}</td>
            <td>{item.total ? `${item.total.toLocaleString()} VND` : '0 VND'}</td>
            <td>{item.customerName || 'Không có tên'}</td>
            <td>{item.customerPhone || 'Không có SDT'}</td>
            <td>{item.customerAddress || 'Không có địa chỉ'}</td>
            <td>
                <select
                    value={item.status}
                    onChange={(e) => handleStatusChange(e.target.value, item)}
                >
                    <option value="Chờ xử lý">Chờ xử lý</option>
                    <option value="Đang giao">Đang giao</option>
                    <option value="Hoàn tất">Hoàn tất</option>
                    <option value="Đã huỷ">Đã huỷ</option>
                </select>
            </td>
        </tr>
    );

    if (loading) return <div>Loading...</div>;
    if (error) return <div>Error: {error}</div>;

    return (
        <div>
            <h2 className="page-header">Orders</h2>
            <div className="row">
                <div className="col-12">
                    <div className="card">
                        <div className="card__body">
                            <Table
                                limit='10'
                                headData={customerTableHead}
                                renderHead={renderHead}
                                bodyData={orders}
                                renderBody={renderBody}
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Orders;
